'use strict';
(() => {
  const $ = (s, root = document) => root.querySelector(s);
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const state = {user:null, csrfToken:'', categories:[], demoMode:false, generation:0, me:null};
  const main = $('#main');
  const icons = {
    search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',
    pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',
    calendar:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 11h16"/>',
    lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',
    shield:'<path d="m12 3 8 3v6c0 4-8 9-8 9s-8-5-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 12a2 2 0 0 0 4 0"/>',
    photo:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="1.5"/><path d="m4 17 5-5 4 4 3-3 5 5"/>',
    users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5v2"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',
    edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14v6Z"/>',
    back:'<path d="M19 12H5m6-6-6 6 6 6"/>'
  };
  const icon = (name, size = 18) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.info}</svg>`;
  function illustration(category) {
    const key = String(category || '').toLowerCase();
    const svgStart = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 160" fill="none" aria-hidden="true">';
    let body;
    if (/electronic|phone|laptop|headphone/.test(key)) body = '<rect x="40" y="19" width="80" height="122" rx="14" fill="#45534a"/><rect x="45" y="24" width="70" height="112" rx="10" fill="#aebda1"/><path d="M64 25h32l-4 8H68z" fill="#45534a"/><rect x="58" y="47" width="45" height="53" rx="8" fill="#dce6cd"/><path d="m69 81 9-14 11 14" stroke="#8c9e7a" stroke-width="3"/><path d="M68 124h24" stroke="#53634b" stroke-width="3" stroke-linecap="round"/>';
    else if (/id|card|license|passport/.test(key)) body = '<rect x="16" y="38" width="128" height="85" rx="10" fill="#b09c77"/><rect x="21" y="43" width="118" height="75" rx="6" fill="#e7dcbf"/><rect x="32" y="55" width="38" height="49" rx="4" fill="#c7b895"/><circle cx="51" cy="71" r="9" fill="#a6936e"/><path d="M37 98v-4a14 14 0 0 1 28 0v4" fill="#a6936e"/><path d="M82 63h39M82 76h30M82 89h35M82 102h21" stroke="#a8956f" stroke-width="4" stroke-linecap="round"/>';
    else if (/cloth|apparel|jacket|shirt/.test(key)) body = '<path d="m54 28 26 10 26-10 35 30-19 25-15-12v65H53V71L38 83 19 58l35-30Z" fill="#8d9a7c"/><path d="M65 33q15 24 30 0" stroke="#dce3d1" stroke-width="5"/><path d="M80 53v83" stroke="#718164" stroke-width="3"/><path d="M61 90h11m17 0h11" stroke="#c7d1ba" stroke-width="3" stroke-linecap="round"/>';
    else if (/other|key|wallet|personal/.test(key)) body = '<rect x="22" y="47" width="116" height="78" rx="11" fill="#957659"/><path d="M29 53h98v65H29z" stroke="#b69777" stroke-width="2" stroke-dasharray="4 3"/><path d="M24 65h111" stroke="#73563f" stroke-width="2"/><path d="M108 75h33v28h-33a9 9 0 0 1-9-9v-10a9 9 0 0 1 9-9Z" fill="#aa8c6c"/><circle cx="114" cy="89" r="4" fill="#d1bb91"/><path d="M41 47V35h69v12" fill="#c9bd99"/>';
    else body = '<path d="M59 37V28a21 21 0 0 1 42 0v9" stroke="#5d6d51" stroke-width="7"/><path d="M39 48a18 18 0 0 1 18-18h46a18 18 0 0 1 18 18l11 80a13 13 0 0 1-13 14H41a13 13 0 0 1-13-14l11-80Z" fill="#7d8f69"/><path d="M40 53q40-19 80 0" stroke="#62784f" stroke-width="3"/><rect x="44" y="82" width="73" height="45" rx="9" fill="#9caf83"/><path d="M48 94h65" stroke="#62784f" stroke-width="3"/><rect x="76" y="46" width="10" height="18" rx="3" fill="#d1daba"/><path d="M82 87v12" stroke="#d9dfcb" stroke-width="3" stroke-linecap="round"/>';
    return svgStart + body + '</svg>';
  }
  const today = () => { const d = new Date(); return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'); };
  const dateLabel = value => { if (!value) return 'Date unavailable'; const d = new Date(String(value).slice(0,10)+'T12:00:00'); return Number.isNaN(d.valueOf()) ? esc(value) : new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(d); };
  const timeLabel = value => { if (!value) return ''; const d = new Date(value); return Number.isNaN(d.valueOf()) ? String(value) : d.toLocaleString(); };
  function categoryName(id) { const c = state.categories.find(c => String(c.id) === String(id)); return c?.name || String(id || 'Other belongings').replace(/[_-]/g,' ').replace(/\b\w/g, x=>x.toUpperCase()); }
  function subcategoryName(category, id) { const c=state.categories.find(c=>String(c.id)===String(category)); return c?.subcategories?.find(s=>String(s.id)===String(id))?.name || String(id||'').replace(/[_-]/g,' '); }
  function badge(text, cls='') { return `<span class="badge ${cls}">${esc(text)}</span>`; }
  function photoUrl(r) { return `/api/reports/${encodeURIComponent(r.id)}/photo?v=${encodeURIComponent(r.version ?? r.updatedAt ?? '1')}`; }
  function photo(r, extra='') { return r.hasPhoto ? `<img src="${photoUrl(r)}" alt="Photo attached to ${esc(r.title)}" loading="lazy" ${extra}>` : illustration(r.category); }
  function toast(message) { const el=$('#toast'); el.textContent=message; el.classList.add('visible'); clearTimeout(state.toastTimer); state.toastTimer=setTimeout(()=>el.classList.remove('visible'),5500); }
  class ApiError extends Error { constructor(status,data){super(data.message||data.error||`Request failed (${status}).`);this.status=status;this.fields=data.fields||{};this.code=data.error;} }
  async function api(path, options={}) {
    const headers = new Headers(options.headers || {});
    headers.set('Accept','application/json');
    if (options.body && !(options.body instanceof Blob)) { headers.set('Content-Type','application/json'); options.body=JSON.stringify(options.body); }
    if (options.method && !['GET','HEAD'].includes(options.method)) headers.set('X-CSRF-Token',state.csrfToken);
    let response;
    try { response=await fetch('/api'+path,{...options,headers,credentials:'same-origin',cache:'no-store'}); }
    catch (_) { throw new Error('The server could not be reached. Check that the application is running, then try again.'); }
    let data={};
    if (response.status !== 204) { try { data=await response.json(); } catch (_) { data={message:'The server returned an unreadable response. Please try again.'}; } }
    if(data.csrfToken) state.csrfToken=data.csrfToken;
    if (!response.ok) {
      if(response.status===401 && !path.startsWith('/login')){state.user=null;renderHeader();}
      throw new ApiError(response.status,data);
    }
    return data;
  }
  function route() { const hash=(location.hash||'#/search').slice(1); const idx=hash.indexOf('?'); return {path:(idx<0?hash:hash.slice(0,idx))||'/search',params:new URLSearchParams(idx<0?'':hash.slice(idx+1))}; }
  function navigate(path) { if (location.hash === '#'+path) loadRoute(); else location.hash=path; }
  function loggedIn(next) { if(state.user) return true; navigate('/login?next='+encodeURIComponent(next||route().path)); return false; }
  function renderHeader() {
    const path=route().path;
    $('#site-header').innerHTML=`<a class="brand" href="#/search" aria-label="Reunite home">reunite<span class="brand-dot" aria-hidden="true">↗</span></a><nav class="site-nav" aria-label="Main navigation"><a href="#/search" class="${path==='/search'?'active':''}">Find an item</a>${state.user?`<a href="#/dashboard" class="${path==='/dashboard'?'active':''}">My dashboard</a>`:''}${state.user?.role==='ADMIN'?`<a href="#/admin" class="${path==='/admin'?'active':''}">Admin</a>`:''}<a href="#/how-it-works" class="${path==='/how-it-works'?'active':''}">How it works</a></nav><div class="header-actions">${state.user?`<span class="user-chip" title="${esc(state.user.name || state.user.username)}" aria-label="Signed in as ${esc(state.user.name||state.user.username)}">${esc((state.user.name||state.user.username||'U').split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase())}</span><button class="btn btn-quiet" id="sign-out">Sign out</button><a class="btn btn-primary" href="#/new">${icon('plus',15)} Report an item</a>`:`<a class="btn btn-quiet" href="#/login">Sign in</a><a class="btn btn-primary" href="#/register">Create account ${icon('arrow',14)}</a>`}</div>`;
    $('#sign-out')?.addEventListener('click',async e=>{e.currentTarget.disabled=true;try{await api('/logout',{method:'POST'});state.user=null;state.me=null;await refreshSession();toast('You have signed out.');navigate('/search');}catch(err){toast(err.message);e.target.disabled=false;}});
  }
  async function refreshSession(){const s=await api('/session');state.user=s.user||null;state.csrfToken=s.csrfToken||state.csrfToken;state.demoMode=!!s.demoMode;renderHeader();}
  function loading(){main.innerHTML='<div class="loading" role="status">Just a moment…</div>';}
  function errorPage(err) { main.innerHTML=`<div class="container main-error"><div class="eyebrow">Let’s get you back</div><h1>${err.status===404?'This report is not available.':err.status===403?'This page needs permission.':'Something needs attention.'}</h1><p class="muted">${esc(err.status===404?'The report may be private, removed, or unavailable to this account. A private report opens only after your own active lost report qualifies as a match.':err.message)}</p><div class="wrap-actions"><a class="btn btn-primary" href="#/search">Return to search ${icon('arrow',15)}</a>${!state.user?'<a class="btn" href="#/login">Sign in</a>':''}<button class="btn" id="retry-route">Try again</button></div></div>`;$('#retry-route').addEventListener('click',loadRoute); }
  function field(name,label,control,help='',extra='') {return `<div class="field ${extra}"><label for="${esc(name)}">${label}</label>${control}${help?`<p class="field-help" id="${esc(name)}-help">${help}</p>`:''}<span class="field-error" data-error-for="${esc(name)}"></span></div>`;}
  function setFormError(form,err) {
    const box=$('.form-status',form); if(box){box.innerHTML=`<div class="alert alert-error" role="alert">${esc(err.message)}</div>`;box.scrollIntoView({block:'nearest',behavior:'smooth'});}
    $$('[data-error-for]',form).forEach(el=>el.textContent='');$$('[aria-invalid]',form).forEach(el=>el.removeAttribute('aria-invalid'));
    for(const [name,message] of Object.entries(err.fields||{})){const target=$(`[data-error-for="${CSS.escape(name)}"]`,form);if(target)target.textContent=Array.isArray(message)?message.join(' '):String(message);const input=form.elements.namedItem(name);if(input?.setAttribute)input.setAttribute('aria-invalid','true');}
    const first=$('[aria-invalid=true]',form);first?.focus();
    if(err.status===401) {box?.insertAdjacentHTML('beforeend','<a class="text-link" href="#/login">Sign in again to continue.</a>');}
  }
  function setBusy(form,busy,label){const b=$('button[type=submit]',form);if(!b)return;if(busy){b.dataset.label=b.innerHTML;b.disabled=true;b.textContent=label||'Saving…';}else{b.disabled=false;b.innerHTML=b.dataset.label||'Continue';}}
  function formData(form){return Object.fromEntries(new FormData(form).entries());}
  function reportCard(r) {
    const isLost=r.type==='LOST',active=r.status==='OPEN'||r.status==='MATCHED';
    return `<a class="report-card" href="#/reports/${encodeURIComponent(r.id)}" aria-label="View ${esc(r.title)}"><div class="card-photo tone-${esc(String(r.category).toLowerCase())}">${photo(r)}<span class="photo-label ${isLost?'lost':''}"><span class="dot"></span>${isLost?'Lost':'Found'} item</span>${r.visibility==='PRIVATE'?'<span class="photo-private">Private</span>':''}</div><div class="card-content"><div class="card-category">${esc(categoryName(r.category))}${r.subcategory?' / '+esc(subcategoryName(r.category,r.subcategory)):''}</div><h3>${esc(r.title)}</h3><p class="card-desc">${esc(r.description)}</p><div class="card-meta">${icon('pin',12)}<span>${esc(r.location)}</span></div><div class="card-meta">${icon('calendar',12)}<span>${dateLabel(r.eventDate)}</span></div></div><div class="card-bottom"><span><span class="status-dot"></span>${active?'Open report':esc(String(r.status||'').replace(/_/g,' ').toLowerCase())}</span><span>View details <span class="arrow" aria-hidden="true">↗</span></span></div></a>`;
  }
  function emptyState(title,message,action='') {return `<div class="empty-state">${icon('search',28)}<h3>${esc(title)}</h3><p>${esc(message)}</p>${action}</div>`;}
  const categoryOptions = (selected='',blank='All categories')=>`<option value="">${esc(blank)}</option>`+state.categories.map(c=>`<option value="${esc(c.id)}" ${String(selected)===String(c.id)?'selected':''}>${esc(c.name)}</option>`).join('');

  async function renderSearch(params,generation) {
    const query=params.toString();
    const data=await api('/search'+(query?'?'+query:'')); if(generation!==state.generation)return;
    const f=Object.fromEntries(params.entries());
    main.innerHTML=`<div class="container"><section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="eyebrow">Good things find their way back</div><h1 id="hero-title">Lost something?<span>Let’s reunite you.</span></h1><p>A familiar place for misplaced things. Search campus reports, share what you’ve found, and make someone’s day.</p><div class="hero-actions"><a class="btn btn-primary" href="${state.user?'#/new?type=LOST':'#/login?next=%2Fnew%3Ftype%3DLOST'}">I lost something ${icon('arrow',15)}</a><a class="btn" href="${state.user?'#/new?type=FOUND':'#/login?next=%2Fnew%3Ftype%3DFOUND'}">I found something ${icon('plus',15)}</a></div><div class="micro-note">${icon('shield',14)} Your contact information stays private.</div></div><div class="hero-art" aria-hidden="true"><div class="hero-objects"><span class="art-tag">Small things. Big relief.</span>${illustration('bags')}<div class="art-icon-small">${illustration('ids')}</div><span class="art-tag">Found, with a little help. ↗</span></div></div></section><div class="section-rule"></div><div class="search-layout"><aside class="filters" aria-label="Search filters"><div class="filter-head"><h2>Refine your search</h2><button class="link-button" id="clear-filters">Reset all</button></div><form class="filter-form" id="filter-form"><fieldset class="filter-group"><legend>Report type</legend>${[['','All reports'],['FOUND','Found items'],['LOST','Lost items']].map(([v,l])=>`<label class="check"><input type="radio" name="type" value="${v}" ${String(f.type||'')===v?'checked':''}>${l}</label>`).join('')}</fieldset><fieldset class="filter-group"><legend>Category</legend><label class="field"><span class="hidden">Category</span><select class="input filter-input" name="category" aria-label="Category">${categoryOptions(f.category)}</select></label></fieldset><fieldset class="filter-group"><legend>Location</legend><label class="field"><span class="hidden">Location</span><input class="input filter-input" name="location" value="${esc(f.location)}" placeholder="e.g. Leavey Library" maxlength="200" aria-label="Location"></label></fieldset><fieldset class="filter-group"><legend>Date range</legend><label class="field"><span class="field-label optional">From</span><input class="input filter-input" type="date" name="from" value="${esc(f.from)}" max="${today()}" aria-label="From date"></label><label class="field"><span class="field-label optional">To</span><input class="input filter-input" type="date" name="to" value="${esc(f.to)}" max="${today()}" aria-label="To date"></label></fieldset><button class="btn" type="submit">Apply filters ${icon('arrow',13)}</button></form></aside><section aria-label="Search results"><form class="search-bar" id="search-form" role="search">${icon('search',19)}<label for="search-query" class="hidden">Search public item descriptions</label><input id="search-query" name="q" value="${esc(f.q)}" placeholder="What are you looking for?" maxlength="200" autocomplete="off"><button class="btn btn-primary" type="submit">Search</button></form><div class="private-banner">${icon('lock',18)}<div><strong>${state.user?(data.privateCount===null||data.privateCount===undefined?'Private reports are protected':`${Number(data.privateCount)} private found ${Number(data.privateCount)===1?'report matches':'reports match'} your search`):'Some finds are kept private. Your details always are.'}</strong><p>${esc(data.privateCountMessage || (state.user?'Submit your own lost report to see qualifying private matches. A search result count does not unlock report details or photos.':'Sign in to see matching private report counts. Submit a lost report to discover qualifying private matches.'))}</p></div><a class="btn btn-small" href="${state.user?'#/new?type=LOST':'#/login'}">${state.user?'File a lost report':'Sign in'} ${icon('arrow',12)}</a></div><div class="search-summary"><strong>${Number(data.total)||0} public ${(Number(data.total)||0)===1?'report':'reports'}${f.q?' for “'+esc(f.q)+'”':''}</strong><span>Relevance, then newest event</span></div><div class="report-grid">${data.reports?.length?data.reports.map(reportCard).join(''):emptyState('No item matches this search','Try fewer filters or a broader description. Your own lost report can also check for private matches.',`<a class="btn btn-small" href="#/new?type=LOST">File a lost report ${icon('arrow',13)}</a>`)}</div>${Number(data.total)>Number(data.pageSize||12)?`<nav class="pagination" aria-label="Results pages"><button class="btn btn-small" id="page-prev" ${(Number(data.page)||1)<=1?'disabled':''}>← Previous</button><span>Page ${Number(data.page)||1} of ${Math.ceil(Number(data.total)/Number(data.pageSize||12))}</span><button class="btn btn-small" id="page-next" ${(Number(data.page)||1)*Number(data.pageSize||12)>=Number(data.total)?'disabled':''}>Next →</button></nav>`:''}<p class="legend-note">Only active public reports appear here. Matching suggestions are possibilities and never proof of ownership.</p></section></div></div>`;
    const search = page => {const p=new URLSearchParams();const filters=formData($('#filter-form'));for(const [k,v] of Object.entries(filters))if(v)p.set(k,v);const q=$('#search-query').value.trim();if(q)p.set('q',q);if(page>1)p.set('page',page);navigate('/search'+(p.size?'?'+p.toString():''));};
    $('#search-form').addEventListener('submit',e=>{e.preventDefault();search(1);});
    $('#filter-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(form.elements.from.value&&form.elements.to.value&&form.elements.from.value>form.elements.to.value){toast('The beginning date must be on or before the end date.');form.elements.from.focus();return;}search(1);});
    $('#clear-filters').addEventListener('click',()=>navigate('/search'));
    $('#page-prev')?.addEventListener('click',()=>search((Number(data.page)||1)-1));$('#page-next')?.addEventListener('click',()=>search((Number(data.page)||1)+1));
    $$('img',main).forEach(img=>img.addEventListener('error',()=>{img.replaceWith(document.createRange().createContextualFragment(illustration('other')));},{once:true}));
  }

  async function renderReportForm(id,params,generation) {
    if(!loggedIn(id?'/edit/'+id:'/new?'+params.toString()))return;
    let report={type:params.get('type')==='LOST'?'LOST':'FOUND',visibility:'PUBLIC',eventDate:today()};
    if(id){const data=await api('/reports/'+encodeURIComponent(id));if(!data.canEdit)throw new ApiError(403,{message:'Only the owner of an active report can edit it.'});report=data.report;}
    if(generation!==state.generation)return;
    const isEdit=!!id;
    main.innerHTML=`<div class="container"><div class="page-heading"><div class="breadcrumb"><a href="#/search">Find an item</a><span>/</span><span>${isEdit?'Edit report':'Create a report'}</span></div><h1>${isEdit?'Update the details.':'Every reunion starts here.'}</h1><p>${isEdit?'Keep your report accurate so the right match can find you.':'Tell us a little about the item. We’ll look for potential matches while you get on with your day.'}</p></div><div class="form-layout"><form id="report-form"><div class="form-status" aria-live="polite"></div><section class="panel"><div class="panel-title"><span class="panel-number">01</span><div><h2>Start with the basics</h2><p>Fields marked * are required.</p></div></div><fieldset class="field fieldset-plain"><legend class="field-label">What would you like to report? *</legend><div class="type-options">${[['LOST','I lost an item','Find a possible match.'],['FOUND','I found an item','Help it get back home.']].map(([v,l,h])=>`<label class="type-option"><input type="radio" name="type" value="${v}" ${report.type===v?'checked':''} ${isEdit?'disabled':''}><span><strong>${l}</strong><small>${h}</small></span></label>`).join('')}</div></fieldset>${field('title','Item name *',`<input class="input" id="title" name="title" required maxlength="120" value="${esc(report.title)}" placeholder="e.g. Olive green backpack">`)}${field('description','Description *',`<textarea class="input" id="description" name="description" required minlength="10" maxlength="3000" placeholder="Describe the item’s appearance and details you can safely observe.">${esc(report.description)}</textarea>`,'Include a few distinctive words. Keep serial numbers, contact details, and ownership evidence in the private field below.')}<div class="form-grid">${field('category','Category *',`<select class="input" id="category" name="category" required>${categoryOptions(report.category,'Choose a category')}</select>`)}${field('subcategory','Item type <span class="optional">optional</span>',`<select class="input" id="subcategory" name="subcategory"><option value="">Choose a category first</option></select>`)}${field('color','Color <span class="optional">optional</span>',`<input class="input" id="color" name="color" maxlength="40" value="${esc(report.color)}" placeholder="e.g. Black">`)}${field('brand','Brand <span class="optional">optional</span>',`<input class="input" id="brand" name="brand" maxlength="60" value="${esc(report.brand)}" placeholder="Only if you’re sure">`)}</div></section><section class="panel"><div class="panel-title"><span class="panel-number">02</span><div><h2>When & where</h2><p>A possible location is helpful. It does not need to be exact.</p></div></div><div class="form-grid">${field('eventDate','Date lost / found *',`<input class="input" type="date" id="eventDate" name="eventDate" required max="${today()}" value="${esc(String(report.eventDate||'').slice(0,10))}">`)}${field('location','Possible location *',`<input class="input" id="location" name="location" required maxlength="200" value="${esc(report.location)}" placeholder="Building, floor, or campus area">`)}</div></section><section class="panel"><div class="panel-title"><span class="panel-number">03</span><div><h2>A picture helps</h2><p>One optional photo. Avoid faces, names, addresses, and ID numbers.</p></div></div><div class="photo-drop" id="photo-drop">${icon('upload',28)}<p><strong>Choose a photo</strong> or drag it here</p><small>JPEG, PNG, or WebP · up to 10 MiB</small><input type="file" id="photo-file" accept="image/jpeg,image/png,image/webp" aria-label="Upload one report photo"></div><span class="field-error" id="photo-error" role="alert"></span><div id="photo-preview"></div><p class="photo-disclaimer">Photos follow the report’s access rules. The server validates image contents and removes metadata before saving.</p></section><section class="panel"><div class="panel-title"><span class="panel-number">04</span><div><h2>Privacy & ownership</h2><p>A little care makes a safer reunion.</p></div></div><div id="found-visibility" class="field"><div class="visibility-box"><label class="check"><input type="checkbox" name="isPrivate" id="isPrivate" ${report.visibility==='PRIVATE'?'checked':''}><span><strong>Keep this found report private</strong></span></label><p>Checked: search shows only a matching count. Details and photos open only for users with a qualifying lost report. Unchecked: the report is public.</p></div></div><div id="lost-visibility" class="alert alert-info" hidden>${icon('lock',15)} Your lost report is private. It appears in your dashboard and helps unlock qualifying found reports.</div>${field('privateDetails','Private identifying details <span class="optional">optional</span>',`<textarea class="input" id="privateDetails" name="privateDetails" maxlength="2000" placeholder="Unique markings or evidence an administrator can use to assess ownership.">${esc(report.privateDetails)}</textarea>`,'Visible to you and administrators. Excluded from public search and automatic matching.')}<div id="verification-fields">${field('verificationQuestion','Ownership verification question '+(isEdit?'<span class="optional">leave blank to keep existing</span>':'*'),`<input class="input" id="verificationQuestion" name="verificationQuestion" maxlength="300" value="${esc(report.verificationQuestion)}" placeholder="e.g. What distinctive marking is on the underside?">`,'Ask about a safe, observable detail that is not in the public description or photo. Do not open bags or unlock devices.')} ${field('verificationAnswer','Expected answer '+(isEdit?'<span class="optional">leave blank to keep existing</span>':'*'),'<input class="input" id="verificationAnswer" name="verificationAnswer" type="password" autocomplete="off" maxlength="300" placeholder="Stored securely; never shown to claimants">','This answer is checked privately. A possible match alone does not prove ownership.')}</div></section><div class="form-actions"><p>By submitting, you confirm these details are accurate to the best of your knowledge.</p><button class="btn btn-primary" type="submit">${isEdit?'Save changes':'Submit report'} ${icon('arrow',15)}</button></div></form><aside class="form-side"><div class="note-card">${icon('shield',25)}<h3>More care. Better matches.</h3><p>Clear details help. So does knowing what to keep private.</p><ol><li>Describe what you can see. Don’t inspect someone’s private belongings.</li><li>Choose the most accurate category. Leave uncertain optional details blank.</li><li>Keep one identifying detail out of the public description and photo.</li></ol></div><div class="note-card note-card-dark">${icon('lock',23)}<h3>Private means protected.</h3><p>A private report’s photos use the same access checks as its details. A search count never grants access.</p></div></aside></div></div>`;
    const form=$('#report-form');let selectedFile=null,removeExisting=false,previewUrl=null;
    const updateSubcategory=(selected='')=>{const c=state.categories.find(c=>String(c.id)===$('#category').value);$('#subcategory').innerHTML='<option value="">Not sure / leave blank</option>'+(c?.subcategories||[]).map(s=>`<option value="${esc(s.id)}" ${String(s.id)===String(selected)?'selected':''}>${esc(s.name)}</option>`).join('');$('#subcategory').disabled=!c;};
    updateSubcategory(report.subcategory);$('#category').addEventListener('change',()=>updateSubcategory());
    const updateType=()=>{const type=isEdit?report.type:form.elements.type.value;const found=type==='FOUND';$('#found-visibility').hidden=!found;$('#lost-visibility').hidden=found;$('#verification-fields').hidden=!found;$('#verificationQuestion').required=found&&!isEdit;$('#verificationAnswer').required=found&&!isEdit;};
    $$('input[name=type]',form).forEach(el=>el.addEventListener('change',updateType));updateType();
    const updatePreview=()=>{if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}const box=$('#photo-preview');if(selectedFile){previewUrl=URL.createObjectURL(selectedFile);box.innerHTML=`<div class="photo-preview"><img src="${previewUrl}" alt="Selected photo preview"><div><p>${esc(selectedFile.name)} <span class="optional">(${(selectedFile.size/1024/1024).toFixed(2)} MiB)</span></p><button class="link-button" id="remove-photo" type="button">Remove photo</button></div></div>`;}else if(report.hasPhoto&&!removeExisting){box.innerHTML=`<div class="photo-preview"><img src="${photoUrl(report)}" alt="Current report photo"><div><p>Current photo</p><button class="link-button" id="remove-photo" type="button">Remove photo</button></div></div>`;}else box.innerHTML='';$('#remove-photo')?.addEventListener('click',()=>{selectedFile=null;removeExisting=true;$('#photo-file').value='';updatePreview();});};
    const chooseFile=file=>{if(!file)return;const error=$('#photo-error');error.textContent='';if(!['image/jpeg','image/png','image/webp'].includes(file.type)){error.textContent='Choose a JPEG, PNG, or WebP image.';return;}if(file.size>10*1024*1024){error.textContent='The image must be no larger than 10 MiB.';return;}selectedFile=file;removeExisting=false;updatePreview();};
    $('#photo-file').addEventListener('change',e=>chooseFile(e.target.files[0]));
    $('#photo-drop').addEventListener('dragover',e=>{e.preventDefault();e.currentTarget.classList.add('dragging');});$('#photo-drop').addEventListener('dragleave',e=>e.currentTarget.classList.remove('dragging'));$('#photo-drop').addEventListener('drop',e=>{e.preventDefault();e.currentTarget.classList.remove('dragging');if(e.dataTransfer.files.length!==1){$('#photo-error').textContent='Choose one image per report.';return;}chooseFile(e.dataTransfer.files[0]);});updatePreview();
    form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;setBusy(form,true,'Saving report…');const values=formData(form);const type=isEdit?report.type:values.type;const payload={type,visibility:type==='LOST'||values.isPrivate?'PRIVATE':'PUBLIC',title:values.title,description:values.description,category:values.category,subcategory:values.subcategory||'',color:values.color,brand:values.brand,eventDate:values.eventDate,location:values.location,privateDetails:values.privateDetails,verificationQuestion:type==='FOUND'?values.verificationQuestion:'',verificationAnswer:type==='FOUND'?values.verificationAnswer:'',...(isEdit?{version:report.version}:{})};
      let saved;
      try{saved=await api(isEdit?'/reports/'+encodeURIComponent(id):'/reports',{method:isEdit?'PUT':'POST',body:payload});report=saved.report;}
      catch(err){setFormError(form,err);if(err.status===409){$('.form-status',form).insertAdjacentHTML('beforeend',`<p class="field-help">Open this report again to load the latest changes before editing.</p><a class="text-link" href="#/reports/${encodeURIComponent(id)}">View latest report</a>`);}setBusy(form,false);return;}
      try{if(selectedFile){await api('/reports/'+encodeURIComponent(report.id)+'/photo',{method:'POST',headers:{'Content-Type':selectedFile.type,'X-Report-Version':String(report.version)},body:selectedFile});}else if(removeExisting&&report.hasPhoto){await api('/reports/'+encodeURIComponent(report.id)+'/photo',{method:'DELETE',headers:{'X-Report-Version':String(report.version)}});}}
      catch(err){toast('Report saved, but the photo change failed: '+err.message);navigate('/reports/'+encodeURIComponent(report.id));return;}
      if(previewUrl)URL.revokeObjectURL(previewUrl);state.me=null;toast(isEdit?'Your report has been updated.':'Your report is saved. Check your dashboard for potential matches.');navigate('/reports/'+encodeURIComponent(report.id));
    });
  }

  async function renderDetail(id,params,generation) {
    const data=await api('/reports/'+encodeURIComponent(id));if(generation!==state.generation)return;const r=data.report;
    const isFound=r.type==='FOUND';
    main.innerHTML=`<div class="container"><div class="page-heading detail-page-heading"><div class="breadcrumb"><a href="#/search">Find an item</a><span>/</span><span>Report #${esc(r.id)}</span></div></div><div class="detail-layout"><div><div class="detail-photo">${photo(r)}</div><p class="photo-disclaimer">${r.hasPhoto?'Photo provided by the reporter.':'No photo attached. Illustration is a placeholder.'} ${r.visibility==='PRIVATE'?'This photo and report are protected by the same access rules.':''}</p>${data.canEdit?`<div class="alert alert-info">${icon('info',15)} You own this report. ${r.visibility==='PRIVATE'?'It is private.':'Its public details and photo can appear in search.'}</div>`:''}</div><div class="detail-copy"><div class="detail-badges">${badge(isFound?'Found item':'Lost item')}${r.visibility==='PRIVATE'?badge('Private report','badge-private'):badge('Public report','badge-muted')}${badge(r.status||'OPEN','badge-muted')}</div><h1>${esc(r.title)}</h1><p class="detail-description">${esc(r.description)}</p><dl class="facts"><div><dt>Category</dt><dd>${esc(categoryName(r.category))}${r.subcategory?' / '+esc(subcategoryName(r.category,r.subcategory)):''}</dd></div><div><dt>Date ${isFound?'found':'lost'}</dt><dd>${dateLabel(r.eventDate)}</dd></div><div><dt>Possible location</dt><dd>${esc(r.location)}</dd></div><div><dt>Color / brand</dt><dd>${esc([r.color,r.brand].filter(Boolean).join(' · ')||'Not specified')}</dd></div></dl>${r.visibility==='PRIVATE'&&!data.canEdit?`<div class="alert alert-info">${icon('lock',15)} ${state.user?.role==='ADMIN'?'Administrator access. Handle this report confidentially.':'You can view this private report because your active lost report qualifies as a potential match. Ownership still requires verification.'}</div>`:''}<div class="detail-buttons">${data.canEdit?`<a class="btn btn-primary" href="#/edit/${encodeURIComponent(r.id)}">${icon('edit',15)} Edit report</a><button class="btn btn-danger" id="remove-report">Remove report</button>`:isFound&&!state.user?'<a class="btn btn-primary" href="#/login?next='+encodeURIComponent('/reports/'+r.id)+'">Sign in to claim '+icon('arrow',15)+'</a>':''}<a class="btn ${data.canEdit?'':'btn-quiet'}" href="#/search">Back to search</a></div>${(data.canEdit||state.user?.role==='ADMIN')&&r.privateDetails?`<section class="section-spacer"><h3>Private identifying details</h3><p class="field-help readable">${esc(r.privateDetails)}</p></section>`:''}</div></div>${data.canClaim?`<section class="panel claim-panel"><div class="panel-title"><span class="panel-number">${icon('shield',15)}</span><div><h2>Could this be yours?</h2><p>Give a private answer. An administrator reviews eligible claims before approving ownership.</p></div></div><form id="claim-form"><div class="form-status" aria-live="polite"></div><div id="claim-lost-select"></div>${field('answer',esc(data.verificationQuestion||'Ownership verification answer')+' *','<input class="input" id="answer" name="answer" required maxlength="500" autocomplete="off" placeholder="Your answer is not shared publicly">')}${field('explanation','Additional evidence <span class="optional">optional</span>','<textarea class="input" id="explanation" name="explanation" maxlength="2000" placeholder="Describe other details that help establish ownership."></textarea>')}<button class="btn btn-primary" type="submit">Submit a claim ${icon('arrow',15)}</button><p class="claim-notice">Up to three attempts per item in 24 hours. Claims do not reserve ownership. Correct answers are never revealed after an unsuccessful attempt.</p></form></section>`:isFound&&state.user&&!data.canEdit&&(r.status==='OPEN'||r.status==='MATCHED')?'<div class="panel"><p class="muted">A claim is not currently available for this account. Check your dashboard for an existing claim or submit your own lost report.</p><a class="btn btn-small" href="#/dashboard">My dashboard</a></div>':''}</div>`;
    $('#remove-report')?.addEventListener('click',async e=>{if(!confirm('Remove this report from search and matching? It will remain in your history.'))return;const button=e.currentTarget;button.disabled=true;try{await api('/reports/'+encodeURIComponent(r.id)+'?version='+encodeURIComponent(r.version),{method:'DELETE'});state.me=null;toast('Report removed. You can still find it in your history.');navigate('/dashboard');}catch(err){toast(err.message);button.disabled=false;}});
    if(data.canClaim){
      let ownLost=[];try{const me=await api('/me');ownLost=(me.reports||[]).filter(x=>x.type==='LOST'&&['OPEN','MATCHED'].includes(x.status));}catch(_){}
      if(generation!==state.generation)return;
      if(ownLost.length)$('#claim-lost-select').innerHTML=field('lostReportId','Link your lost report <span class="optional">recommended</span>',`<select class="input" id="lostReportId" name="lostReportId"><option value="">Choose an active lost report</option>${ownLost.map(l=>`<option value="${esc(l.id)}" ${String(l.id)===params.get('lost')?'selected':''}>#${esc(l.id)} — ${esc(l.title)}</option>`).join('')}</select>`);
      $('#claim-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;setBusy(form,true,'Submitting…');const v=formData(form);try{await api('/claims',{method:'POST',body:{foundReportId:r.id,...(v.lostReportId?{lostReportId:Number(v.lostReportId)}:{}),answer:v.answer,explanation:v.explanation}});state.me=null;toast('Claim submitted. Follow its status in your dashboard.');navigate('/dashboard?tab=claims');}catch(err){setFormError(form,err);form.elements.answer.value='';setBusy(form,false);}});
    }
  }

  async function renderDashboard(params,generation) {
    if(!loggedIn('/dashboard'))return;const data=await api('/me');if(generation!==state.generation)return;state.me=data;
    const reports=data.reports||[],matches=data.matches||[],claims=data.claims||[],notifications=data.notifications||[];const tab=['reports','matches','claims','notifications'].includes(params.get('tab'))?params.get('tab'):'reports';
    const names={reports:'My reports',matches:'Potential matches',claims:'My claims',notifications:'Notifications'};
    let content;
    if(tab==='reports')content=`<div class="section-heading"><h2>Your reports</h2><a class="btn btn-small btn-primary" href="#/new">${icon('plus',13)} Create a report</a></div><div class="report-grid">${reports.length?reports.map(reportCard).join(''):emptyState('Your next reunion starts here','Create a lost or found report to keep track of it here.','<a class="btn btn-small" href="#/new">Create a report</a>')}</div>`;
    if(tab==='matches')content=`<div class="section-heading"><h2>Potential matches</h2></div><div class="alert alert-info">These reports qualify as possibilities based on your active lost reports. Scores rank similarity; they do not establish ownership. Private access ends if the qualifying lost report is removed or no longer matches.</div>${matches.length?matches.map(m=>{const r=m.foundReport||m.report||{};return `<article class="match-card"><div class="match-photo">${photo(r)}</div><div><div class="match-score">${Number(m.score||0).toFixed(0)} / 100 similarity ${r.visibility==='PRIVATE'?'· Private match':''}</div><h3>${esc(r.title||'Potential match')}</h3><p>For your lost report #${esc(m.lostReportId)} · ${esc(r.location)} · ${dateLabel(r.eventDate)}</p><p>${esc((m.reasons||[]).join(' · '))}</p></div><div><a class="btn btn-small btn-primary" href="#/reports/${encodeURIComponent(r.id)}?lost=${encodeURIComponent(m.lostReportId)}">View match ${icon('arrow',12)}</a></div></article>`;}).join(''):emptyState('No qualifying matches yet','New found reports will be checked against your active lost reports. Add accurate details to help a good match stand out.','<a class="btn btn-small" href="#/new?type=LOST">File a lost report</a>')}`;
    if(tab==='claims')content=`<div class="section-heading"><h2>Your claims</h2></div>${claims.length?claims.map(c=>`<article class="list-card"><div class="list-card-top"><h3>Claim #${esc(c.id)} ${c.foundTitle?'· '+esc(c.foundTitle):'for report #'+esc(c.foundReportId)}</h3>${badge(c.status,'status-'+String(c.status||'').toLowerCase())}</div><p>Submitted ${esc(timeLabel(c.createdAt||c.submittedAt))}${c.deadline?' · Respond by '+esc(timeLabel(c.deadline)):''}</p>${c.reason?'<p>'+esc(c.reason)+'</p>':''}${c.explanation?'<p><strong>Your supporting information:</strong> '+esc(c.explanation)+'</p>':''}</article>`).join(''):emptyState('No claims submitted','When a found item looks like yours, open its report and answer the ownership question.')}`;
    if(tab==='notifications')content=`<div class="section-heading"><h2>Your notifications</h2></div>${notifications.length?notifications.map(n=>`<article class="list-card"><div class="list-card-top"><h3>${icon('bell',16)} ${esc(n.message||n.title)}</h3><time>${esc(timeLabel(n.createdAt))}</time></div></article>`).join(''):emptyState('You’re all caught up','Match and claim updates will appear here.')}`;
    main.innerHTML=`<div class="container"><div class="page-heading"><div class="eyebrow">Your corner of campus</div><h1>Hello, ${esc((state.user.name||state.user.username).split(' ')[0])}.</h1><p>Keep an eye on your reports, follow possible matches, and track each step toward a reunion.</p></div><div class="dashboard-summary"><div class="stat"><strong>${reports.filter(r=>['OPEN','MATCHED'].includes(r.status)).length}</strong><span>Active reports</span></div><div class="stat"><strong>${matches.length}</strong><span>Potential matches</span></div><div class="stat"><strong>${claims.filter(c=>['PENDING','QUEUED'].includes(c.status)).length}</strong><span>Open claims</span></div></div><nav class="tabs" aria-label="Dashboard sections">${Object.entries(names).map(([key,label])=>`<a class="tab" role="tab" aria-selected="${key===tab}" href="#/dashboard?tab=${key}">${label}${key==='matches'&&matches.length?' ('+matches.length+')':''}</a>`).join('')}</nav><div class="dashboard-body">${content}</div></div>`;
  }

  async function renderAuth(isRegister,params) {
    if(state.user){navigate('/dashboard');return;}
    main.innerHTML=`<div class="container auth-wrap"><section class="auth-intro"><div class="eyebrow">A little help goes a long way</div><h1>${isRegister?'Your campus.<br>Your community.':'Good to have<br>you back.'}</h1><p>${isRegister?'Join a more thoughtful lost and found. A few details are all it takes to start reconnecting people with their things.':'Sign in to manage your reports, see private report counts, and discover potential matches.'}</p><div class="privacy-points"><div class="privacy-point">${icon('lock',19)}<div><strong>Private by design</strong><p>Your contact details and ownership evidence stay out of search.</p></div></div><div class="privacy-point">${icon('search',19)}<div><strong>Thoughtful matching</strong><p>Your lost report can unlock qualifying private finds.</p></div></div><div class="privacy-point">${icon('users',19)}<div><strong>A human final step</strong><p>Potential matches never automatically establish ownership.</p></div></div></div></section><div><section class="panel auth-panel"><h2>${isRegister?'Create your account':'Sign in to Reunite'}</h2><p class="muted">${isRegister?'Let’s get you connected.':'Your reports and matches are waiting.'}</p><form id="auth-form"><div class="form-status" aria-live="polite"></div>${isRegister?field('name','Full name','<input class="input" id="name" name="name" required maxlength="100" autocomplete="name">')+field('email','Email address','<input class="input" id="email" name="email" type="email" required maxlength="254" autocomplete="email">'):''}${field('username','Username','<input class="input" id="username" name="username" required maxlength="40" autocomplete="username" autocapitalize="none" spellcheck="false">')}${field('password','Password',`<input class="input" id="password" name="password" type="password" required ${isRegister?'minlength="8" maxlength="128"':''} autocomplete="${isRegister?'new-password':'current-password'}">`,isRegister?'8–128 characters, at least one uppercase letter and one digit, with no run of three identical characters.':'')}${isRegister?field('confirmPassword','Confirm password','<input class="input" id="confirmPassword" name="confirmPassword" type="password" required minlength="8" maxlength="128" autocomplete="new-password">'):''}<button type="submit" class="btn btn-primary">${isRegister?'Create account':'Sign in'} ${icon('arrow',15)}</button></form><p class="auth-tail">${isRegister?'Already have an account? <a class="text-link" href="#/login">Sign in</a>':'New around here? <a class="text-link" href="#/register">Create an account</a>'}</p></section>${state.demoMode?`<div class="demo-note"><strong>Local demonstration</strong><br>${isRegister?'New demo accounts activate immediately. This local build does not send verification emails.':'Use a seeded account to explore the privacy and matching workflow.'}<div class="demo-accounts"><button class="btn btn-small" data-demo="alice">Alice</button><button class="btn btn-small" data-demo="bob">Bob</button><button class="btn btn-small" data-demo="admin">Administrator</button></div><p class="demo-passwords">Alice: <code>AliceDemo1!</code> · Bob: <code>BobDemo1!</code><br>Administrator: <code>AdminDemo1!</code></p></div>`:''}</div></div>`;
    $$('[data-demo]').forEach(b=>b.addEventListener('click',()=>{const u=b.dataset.demo;$('#username').value=u;$('#password').value={alice:'AliceDemo1!',bob:'BobDemo1!',admin:'AdminDemo1!'}[u];if(isRegister){navigate('/login');return;}$('#auth-form button[type=submit]').focus();}));
    $('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const v=formData(form);if(isRegister&&v.password!==v.confirmPassword){setFormError(form,{message:'Your password confirmation does not match.',fields:{confirmPassword:'Enter the same password in both fields.'}});form.elements.password.value='';form.elements.confirmPassword.value='';return;}setBusy(form,true,isRegister?'Creating account…':'Signing in…');try{const data=await api(isRegister?'/register':'/login',{method:'POST',body:isRegister?{name:v.name,email:v.email,username:v.username,password:v.password}:{username:v.username,password:v.password}});state.user=data.user||null;await refreshSession();toast(isRegister?'Your account is ready. Welcome to Reunite.':'You’re signed in.');let next=params.get('next')||'/dashboard';if(!/^\/(?:search|dashboard|new|reports\/\d+|edit\/\d+|admin)(?:\?|$)/.test(next))next='/dashboard';navigate(next);}catch(err){setFormError(form,err);form.elements.password.value='';if(form.elements.confirmPassword)form.elements.confirmPassword.value='';setBusy(form,false);}});
  }

  async function renderAdmin(generation) {
    if(!loggedIn('/admin'))return;if(state.user.role!=='ADMIN')throw new ApiError(403,{message:'This page is available to administrators.'});
    const data=await api('/admin');if(generation!==state.generation)return;
    const claims=data.claims||[],reports=data.reports||[],users=data.users||[],audit=data.audit||[];
    main.innerHTML=`<div class="container"><div class="page-heading"><div class="eyebrow">Administrator workspace</div><h1>Review with care.</h1><p>Review ownership evidence and record a reason for every decision. Matching scores support review; they do not prove ownership.</p></div><div class="alert alert-warning">Confidential workspace. Do not copy private report details or claim evidence into public descriptions.</div><div class="dashboard-summary"><div class="stat"><strong>${claims.filter(c=>['PENDING','QUEUED'].includes(c.status)).length}</strong><span>Claims awaiting review</span></div><div class="stat"><strong>${reports.length}</strong><span>Reports</span></div><div class="stat"><strong>${users.length}</strong><span>Accounts</span></div></div><div class="dashboard-body admin-section"><h2>Ownership claims</h2><div id="admin-status" aria-live="polite"></div>${claims.length?claims.map(c=>`<article class="panel admin-claim"><div class="list-card-top"><h3>Claim #${esc(c.id)} · Found report #${esc(c.foundReportId)}</h3>${badge(c.status,'status-'+String(c.status||'').toLowerCase())}</div><p class="field-help">Claimant ${esc(c.claimantName||c.username||c.claimantId||c.userId)} · ${esc(timeLabel(c.createdAt||c.submittedAt))}</p><dl><dt>Submitted ownership evidence</dt><dd>${esc(c.answer||c.submittedAnswer||'(Answer is checked privately by the server.)')}</dd>${c.answerMatches!==undefined?`<dt>Answer check</dt><dd>${c.answerMatches?'Matches stored answer':'Does not match stored answer'}</dd>`:''}<dt>Additional explanation</dt><dd>${esc(c.explanation||'No additional evidence supplied.')}</dd></dl>${c.reason?'<p class="field-help">Decision: '+esc(c.reason)+'</p>':''}${c.status==='PENDING'?`<form class="admin-decision-form" data-id="${esc(c.id)}"><div class="form-status"></div><div class="form-grid">${field('reason-'+c.id,'Decision reason *',`<input class="input" id="reason-${esc(c.id)}" name="reason" required minlength="5" maxlength="500" placeholder="Record the evidence behind your decision">`)}<div class="field"><label for="decision-${esc(c.id)}">Decision</label><select class="input" id="decision-${esc(c.id)}" name="decision"><option value="APPROVED">Approve ownership</option><option value="REJECTED">Reject claim</option></select></div></div><button class="btn btn-primary btn-small" type="submit">Record decision ${icon('check',13)}</button></form>`:c.status==='QUEUED'?'<p class="field-help">This claim is queued. Only the current pending claim may be decided.</p>':''}</article>`).join(''):emptyState('No claims to review','Claims will appear here when someone submits ownership evidence.')}<h2>Report register</h2><div class="table-wrap"><table><thead><tr><th>Report</th><th>Type / visibility</th><th>Status</th><th>Event date</th></tr></thead><tbody>${reports.map(r=>`<tr><td><a class="text-link" href="#/reports/${encodeURIComponent(r.id)}">#${esc(r.id)} · ${esc(r.title)}</a></td><td>${esc(r.type)} · ${esc(r.visibility)}</td><td>${esc(r.status)}</td><td>${dateLabel(r.eventDate)}</td></tr>`).join('')||'<tr><td colspan="4">No reports.</td></tr>'}</tbody></table></div><h2>Accounts</h2><div class="table-wrap"><table><thead><tr><th>Account</th><th>Name</th><th>Role</th></tr></thead><tbody>${users.map(u=>`<tr><td>#${esc(u.id)} · ${esc(u.username)}</td><td>${esc(u.name||u.fullName)}</td><td>${esc(u.role)}</td></tr>`).join('')||'<tr><td colspan="3">No accounts.</td></tr>'}</tbody></table></div><h2>Decision history</h2><div class="table-wrap"><table><thead><tr><th>When</th><th>Actor / action</th><th>Reason</th></tr></thead><tbody>${audit.map(a=>`<tr><td>${esc(timeLabel(a.createdAt))}</td><td>${esc(a.actorName||a.actorId||a.userId)} · ${esc(a.action)}${a.targetId?' #'+esc(a.targetId):''}</td><td class="break-word">${esc(a.reason||a.details)}</td></tr>`).join('')||'<tr><td colspan="3">No administrative decisions recorded.</td></tr>'}</tbody></table></div></div></div>`;
    $$('.admin-decision-form').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;setBusy(form,true,'Recording…');const v=formData(form);try{await api('/admin/claims/'+encodeURIComponent(form.dataset.id)+'/decision',{method:'POST',body:v});toast('Decision recorded.');loadRoute();}catch(err){setFormError(form,err);setBusy(form,false);}}));
  }

  function renderHowItWorks(){main.innerHTML=`<div class="container"><div class="page-heading"><div class="eyebrow">A clearer path back</div><h1>How a reunion happens.</h1><p>Share useful details, protect ownership evidence, and let a careful matching process connect the dots.</p></div><div class="form-layout"><div><section class="panel"><div class="panel-title"><span class="panel-number">01</span><div><h2>Search the public reports</h2><p>Anyone can browse active public items by description, category, date, or possible location.</p></div></div><p class="muted">Signed-in users can also see how many private found reports meet their search. A count never exposes private report titles, details, photos, or ownership evidence.</p></section><section class="panel"><div class="panel-title"><span class="panel-number">02</span><div><h2>Submit your own lost report</h2><p>Your report needs enough accurate detail to qualify as a match.</p></div></div><p class="muted">The system checks item type and date compatibility, then ranks descriptive similarity and other available evidence. A qualifying match gives you access to that private found report while your lost report remains active and compatible.</p></section><section class="panel"><div class="panel-title"><span class="panel-number">03</span><div><h2>Verify ownership privately</h2><p>Open a found report, answer its ownership question, and add supporting information.</p></div></div><p class="muted">Administrators review claims before confirming ownership. Similarity scores do not prove an item belongs to you. Claim attempts are limited, and an unsuccessful attempt never reveals the expected answer.</p></section><div class="wrap-actions"><a class="btn btn-primary" href="#/search">Find an item ${icon('arrow',15)}</a><a class="btn" href="#/new">Create a report</a></div></div><aside><div class="note-card">${icon('lock',24)}<h3>You choose what to share.</h3><p>When creating a found report, check “Keep this found report private” to protect its details and photo. Leave it unchecked to publish those details in search.</p><p>Private identifying information and verification answers stay protected in either case.</p></div><div class="note-card"><h3>Be specific. Be safe.</h3><p>Choose reliable item categories, keep uncertain attributes blank, and describe only what you can safely observe. Avoid opening bags or unlocking someone else’s device.</p></div></aside></div></div>`;}

  async function loadRoute() {
    const generation=++state.generation;const {path,params}=route();renderHeader();loading();document.title='Reunite · Campus lost & found';
    try {
      if(path==='/search'||path==='/')await renderSearch(params,generation);
      else if(path==='/new')await renderReportForm(null,params,generation);
      else if(/^\/edit\/\d+$/.test(path))await renderReportForm(path.split('/')[2],params,generation);
      else if(/^\/reports\/\d+$/.test(path))await renderDetail(path.split('/')[2],params,generation);
      else if(path==='/dashboard')await renderDashboard(params,generation);
      else if(path==='/login'||path==='/register')await renderAuth(path==='/register',params);
      else if(path==='/admin')await renderAdmin(generation);
      else if(path==='/how-it-works')renderHowItWorks();
      else throw new ApiError(404,{message:'This page does not exist.'});
      if(generation===state.generation){window.scrollTo(0,0);main.focus({preventScroll:true});}
    }catch(err){if(generation===state.generation)errorPage(err);}
  }
  async function boot(){try{const session=await api('/session');const categories=await api('/categories');state.user=session.user||null;state.csrfToken=session.csrfToken||'';state.demoMode=!!session.demoMode;state.categories=categories.categories||[];window.addEventListener('hashchange',loadRoute);await loadRoute();}catch(err){renderHeader();errorPage(err);}}
  $('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
  boot();
})();
